package main

import "embed"

// The icons are generated by tools/icongen in the main module
// (go run ./tools/icongen from the repo root); do not edit them by hand.
//
//go:embed assets/icon.ico assets/icon-pending.ico assets/icon.png assets/icon-pending.png
var assets embed.FS

// iconBytes returns the tray icon for goos: .ico on Windows (systray needs
// it there), PNG elsewhere. pending selects the variant with a badge.
func iconBytes(goos string, pending bool) []byte {
	name := "assets/icon"
	if pending {
		name += "-pending"
	}
	if goos == "windows" {
		name += ".ico"
	} else {
		name += ".png"
	}
	b, err := assets.ReadFile(name)
	if err != nil {
		panic("rocket-tray: missing embedded icon " + name) // embed guarantees it
	}
	return b
}
